    INSERT INTO [QBOT_JOIN_TEST].[FACT_INVENTORY_MONTHLY]
        ([MONTHLY_SNAPSHOT_KEY], [PERIOD_DATE_KEY], [PRODUCT_KEY], [WAREHOUSE_KEY],
         [CLOSING_QUANTITY], [CLOSING_VALUE])
    VALUES
        (1, 20260131, 100, 10, 22.000, 1100.00),
