    INSERT INTO [QBOT_JOIN_TEST].[TEST_EXPECTED_CASES]
        ([CASE_ID], [CAPABILITY], [QUESTION_TEXT], [EXPECTED_ANCHOR], [EXPECTED_GRAIN],
