        (2, 'snowflake',
         'Show revenue by region.', 'FACT_SALES', 'region',
         720.0000, 'Northern Region=640.00; Southern Region=80.00', 0,
         'Use FACT_SALES -> DIM_WAREHOUSE -> DIM_REGION; do not invent FACT_SALES.REGION_KEY.'),
